<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireRole('customer');

$pdo = db();
$userId = (int) Auth::userId();

$stmt = $pdo->prepare('SELECT name,email,phone,created_at FROM users WHERE id=? LIMIT 1');
$stmt->execute([$userId]);
$user = $stmt->fetch() ?: [];

$stmt = $pdo->prepare('SELECT COUNT(*) FROM orders WHERE customer_id=?');
$stmt->execute([$userId]);
$orderCount = (int)$stmt->fetchColumn();

$stmt = $pdo->prepare("SELECT COUNT(*) FROM orders WHERE customer_id=? AND status IN ('paid','processing','shipped')");
$stmt->execute([$userId]);
$activeOrders = (int)$stmt->fetchColumn();

$stmt = $pdo->prepare("SELECT COALESCE(SUM(total),0) FROM orders WHERE customer_id=? AND status NOT IN ('cancelled','refunded','pending_payment')");
$stmt->execute([$userId]);
$totalSpent = (float)$stmt->fetchColumn();

$stmt = $pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL');
$stmt->execute([$userId]);
$unread = (int)$stmt->fetchColumn();

$stmt = $pdo->prepare('SELECT order_number,total,status,created_at FROM orders WHERE customer_id=? ORDER BY id DESC LIMIT 5');
$stmt->execute([$userId]);
$recentOrders = $stmt->fetchAll();

$stmt = $pdo->prepare('SELECT subject,message,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 4');
$stmt->execute([$userId]);
$notifications = $stmt->fetchAll();

function dashBadge(string $status): string {
    return match ($status) {
        'completed' => 'success',
        'cancelled','refunded' => 'danger',
        'shipped' => 'info',
        default => 'warning',
    };
}
?>

