<main class="df-wrap"><div class="df-top"><div><span class="df-eyebrow">MY ACCOUNT</span><h1>Welcome back, <?=e((string)($user['name']??'Customer'))?>.</h1><p class="df-sub">Manage your purchases, account details and DogoFlow activity.</p></div><a class="df-btn df-primary" href="<?=e(url('/products.php'))?>">Continue shopping</a></div><section class="df-stats"><div class="df-card df-stat"><span>ORDERS</span><strong><?=number_format($orderCount)?></strong><small>All purchases</small></div><div class="df-card df-stat"><span>ACTIVE ORDERS</span><strong><?=number_format($activeOrders)?></strong><small>Being fulfilled</small></div><div class="df-card df-stat"><span>TOTAL SPENT</span><strong>GH₵ <?=number_format($totalSpent,2)?></strong><small>Successful orders</small></div><div class="df-card df-stat"><span>NOTIFICATIONS</span><strong><?=number_format($unread)?></strong><small>Unread updates</small></div></section><section class="df-two"><div class="df-card"><div class="df-section"><div class="df-section-head"><div><span class="df-eyebrow">PURCHASES</span><h2>Recent orders</h2></div><a href="<?=e(url('/customer/orders.php'))?>" style="color:var(--df);font-weight:850;text-decoration:none">View all</a></div></div><?php if(!$recentOrders): ?><div class="df-empty"><h3>No orders yet</h3><p>Your purchases will appear here after checkout.</p><a class="df-btn df-primary" href="<?=e(url('/products.php'))?>">Explore products</a></div><?php else: ?><?php foreach($recentOrders as $order): ?><a class="df-order-row" href="<?=e(url('/customer/order.php?id='.(int)($order['id']??0)))?>"><div><strong><?=e((string)$order['order_number'])?></strong><small><?=e(date('d M Y',strtotime((string)$order['created_at'])))?></small></div><div class="df-order-right"><strong>GH₵ <?=number_format((float)$order['total'],2)?></strong><span class="df-badge <?=e(dashBadge((string)$order['status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$order['status'])))?></span></div></a><?php endforeach; ?><?php e